//! Built-in [`LexiconCatalog::bundled()`] containing all generated core Petrel schemas.

use std::sync::OnceLock;

use crate::catalog::{LexiconCatalog, LexiconCatalogError};
use crate::generated::bundled_lexicon_documents;
use crate::schema::LexiconSchemaOptions;

static BUNDLED_CATALOG: OnceLock<Result<LexiconCatalog, LexiconCatalogError>> = OnceLock::new();

impl LexiconCatalog {
    /// Returns the built-in catalog of all core AT Protocol Lexicons generated by `petrel-api`.
    ///
    /// Built once on first call with [`LexiconSchemaOptions::lenient()`] (because the bundled
    /// corpus includes permissioned-spaces draft lexicons using `"space"` and `"space-ref"`),
    /// and cached for subsequent callers.
    pub fn bundled() -> Result<&'static Self, LexiconCatalogError> {
        let cached = BUNDLED_CATALOG.get_or_init(|| {
            let mut catalog = Self::new();
            for raw in bundled_lexicon_documents::ALL {
                catalog.add_json(raw.as_bytes(), LexiconSchemaOptions::lenient())?;
            }
            Ok(catalog)
        });
        match cached {
            Ok(catalog) => Ok(catalog),
            Err(err) => Err(err.clone()),
        }
    }

    /// Number of bundled Lexicon documents compiled into this crate.
    pub const fn bundled_count() -> usize {
        bundled_lexicon_documents::COUNT
    }
}
